#[test]
fn ensure_provision_copies_by_cid_then_reuses_offline_materialization() {
    let source = tempfile::tempdir().unwrap();
    let module = provision(source.path(), "upper-v1");
    let address = unused_address();
    let server = spawn_server(source.path(), &address, &module);
    let receiver = tempfile::tempdir().unwrap();

    let copied = ensure(receiver.path(), &address, &module);
    assert_eq!(copied["accepted"], true);
    assert_eq!(
        copied["schema"],
        "unicodex.foreign_process.ensure_provision_result.v1"
    );
    assert_eq!(copied["module_cid"], module);
    assert_eq!(copied["source"], "peer_fetch");
    assert_eq!(copied["automatic_replication_by_cid"], true);
    assert_eq!(copied["idempotent_materialization"], true);
    assert_eq!(copied["local_reused"], false);
    assert_eq!(copied["fetch_network_requests"], 1);
    assert!(copied["downloaded_objects"].as_u64().unwrap() > 1);
    assert!(copied["promotion_objects_written"].as_u64().unwrap() > 1);
    assert_state_and_authority(&copied);
    assert!(server.wait_with_output().unwrap().status.success());

    let reused = ensure(receiver.path(), &address, &module);
    assert_eq!(reused["accepted"], true);
    assert_eq!(reused["source"], "local_reuse");
    assert_eq!(reused["local_reused"], true);
    assert_eq!(reused["fetch_network_requests"], 0);
    assert_eq!(reused["downloaded_objects"], JsonValue::Null);
    assert_eq!(reused["promotion_objects_written"], 0);
    assert_state_and_authority(&reused);

    let invoked = run_json(
        receiver.path(),
        [
            "program",
            "module",
            "foreign-process",
            "invoke",
            &module,
            "--input",
            "replicated",
            "--format",
            "json",
        ],
    );
    assert_eq!(invoked["accepted"], true);
    assert_eq!(invoked["result"], "v1:REPLICATED");
    assert_eq!(invoked["sandbox_enforced"], true);
    assert_eq!(invoked["network_authorized"], false);
    println!("ensure_provision_checkpoint={copied}");
}

#[test]
fn ensure_provision_rejects_missing_cid_without_local_or_remote_disclosure() {
    let receiver = tempfile::tempdir().unwrap();
    let missing = "ucx1bffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff";
    let output = ensure_raw(receiver.path(), &unused_address(), missing);
    assert_eq!(output.status.code(), Some(2));
    assert!(output.stderr.is_empty());
    let rejected: JsonValue = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(rejected["accepted"], false);
    assert_eq!(rejected["built"], false);
    assert_eq!(rejected["provisioned"], false);
    assert_eq!(rejected["activated"], false);
    assert_eq!(rejected["default_deployed"], false);
    assert_eq!(rejected["grants_activation_authority"], false);
    assert_eq!(
        ObjectStore::open(receiver.path())
            .verify_object(missing)
            .status,
        RefStatus::Missing
    );
}

