function exactBoundedPermille(numerator: number, denominator: number): number {
  const denominatorThousands = Math.floor(denominator / 1_000);
  const denominatorRemainder = denominator % 1_000;
  let low = 0;
  let high = 1_000;
  while (low < high) {
    const candidate = Math.ceil((low + high) / 2);
    const minimumNumerator = denominatorThousands * candidate
      + Math.ceil(denominatorRemainder * candidate / 1_000);
    if (numerator >= minimumNumerator) low = candidate;
    else high = candidate - 1;
  }
  return low;
}

